def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    # instructions[i][j] -> instruction of core i at cycle j (0‑indexed)
    instructions = []
    for i in range(n):
        row = []
        for j in range(m):
            row.append(int(next(it)))
        instructions.append(row)

