    for cycle in range(m):          # cycle 0 corresponds to cycle 1 in problem
        writes_to = {}              # cell -> list of cores trying to write this cycle
        for core in range(n):
            if locked_core[core] != -1:
                continue            # already locked
            cell = instructions[core][cycle]
            if cell == 0:
                continue
            writes_to.setdefault(cell, []).append(core)

        # Check each cell that is written to this cycle
        for cell, writers in writes_to.items():
            if locked_cell[cell]:
                # Cell already locked -> all writers get locked now
                for core in writers:
                    if locked_core[core] == -1:
                        locked_core[core] = cycle + 1
            else:
                if len(writers) > 1:
                    # Conflict: lock the cell and all writers
                    locked_cell[cell] = True
                    for core in writers:
                        if locked_core[core] == -1:
                            locked_core[core] = cycle + 1

    # Output
    out_lines = []
    for core in range(n):
        if locked_core[core] == -1:
            out_lines.append("0")
        else:
            out_lines.append(str(locked_core[core]))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
